        '乙丑日,趙盾嘅堂弟將軍趙穿喺桃園襲殺咗靈公並迎接趙盾。',
      vernacularMandarin:
        '乙丑日,趙盾的堂弟將軍趙穿在桃園襲殺了靈公並迎接趙盾。',
